INSERT INTO onboarding_tasks(id,title,guidance,sort_order,action_url) VALUES
('consent-news','Учебное согласие на новости','В учебном сервисе откройте «Внутренние новости» и предоставьте согласие. Это синтетический сценарий: согласие можно отозвать. Объясните наставнику разницу между добровольными согласиями и обязательной обработкой данных. Само действие не одобряет этап.',100,'http://localhost:5185/')
INSERT INTO knowledge_articles(id,title,url,content) VALUES
('consents','Учебные согласия','http://localhost:5185/','В учебном сервисе согласий можно предоставить или отозвать согласие на внутренние новости и публикацию фото. Рабочие данные показаны отдельно. Согласия добровольны. Изменение сохраняется сервером для текущего стажёра. Агент может проверить текущее состояние, но не меняет согласия и не одобряет этап онбординга.')
